using B=std::vector<uint8_t>;using W=std::array<int,3>;using U=uint64_t;
void ck(bool x,const char*s){if(!x)throw std::runtime_error(s);}struct Shape{int z,y,x,c;size_t n()const{return size_t(z)*y*x*c;}size_t at(int a,int b,int d,int e)const{return ((size_t(a)*y+b)*x+d)*c+e;}};
B xorv(const B&a,const B&b){B r(a.size());for(size_t i=0;i<r.size();++i)r[i]=a[i]^b[i];return r;}
B rle(const B&a){B o;for(size_t i=0;i<a.size();){size_t j=i;if(!a[i]){while(j<a.size()&&!a[j]&&j-i<128)++j;o.push_back(128|uint8_t(j-i-1));}else{while(j<a.size()&&a[j]&&j-i<128)++j;o.push_back(uint8_t(j-i-1));o.insert(o.end(),a.begin()+i,a.begin()+j);}i=j;}return o;}
B unrle(const B&a,size_t n){B o;for(size_t i=0;i<a.size();){int t=a[i++],k=(t&127)+1;ck(o.size()+k<=n,"rle overflow");if(t&128)o.insert(o.end(),k,0);else{ck(i+k<=a.size(),"rle short");o.insert(o.end(),a.begin()+i,a.begin()+i+k);i+=k;}}ck(o.size()==n,"rle size");return o;}
B zip(const B&a){uLongf n=compressBound(a.size());B b(n);ck(compress2(b.data(),&n,a.data(),a.size(),1)==Z_OK,"zip");b.resize(n);return b;}
B unzip(const B&a,size_t n){B b(n);uLongf k=n;uLong s=a.size();ck(uncompress2(b.data(),&k,a.data(),&s)==Z_OK&&k==n&&s==a.size(),"unzip");return b;}
uint32_t crc(const B&a){return crc32(0,a.data(),a.size());}void put32(std::ostream&f,uint32_t x){for(int i=0;i<4;++i)f.put(char(x>>(8*i)));}
struct Packet{int mode=0;B body;W w={16,0,0};size_t size()const{return 9+body.size()+((mode==4||mode==8)?3:0);}};
struct Kernel{Shape s;std::vector<std::array<size_t,6>> nb;Kernel(Shape q):s(q),nb(q.n()){for(int z=0;z<s.z;++z)for(int y=0;y<s.y;++y)for(int x=0;x<s.x;++x)for(int c=0;c<s.c;++c){nb[s.at(z,y,x,c)]={s.at((z+1)%s.z,y,x,c),s.at((z+s.z-1)%s.z,y,x,c),s.at(z,(y+1)%s.y,x,c),s.at(z,(y+s.y-1)%s.y,x,c),s.at(z,y,(x+1)%s.x,c),s.at(z,y,(x+s.x-1)%s.x,c)};}}
 B motion(const B&p)const{B m(p.size());for(size_t i=0;i<p.size();++i)m[i]=p[nb[i][5]];return m;}B mean(const B&p)const{B m(p.size());for(size_t i=0;i<p.size();++i){int t=0;for(auto j:nb[i])t+=p[j];m[i]=(t+3)/6;}return m;} B ann(const B&p,const B&m,const B&a,W w)const{B r(p.size());for(size_t i=0;i<p.size();++i)r[i]=(w[0]*p[i]+w[1]*m[i]+w[2]*a[i]+8)>>4;return r;}
 B decode(const Packet&p,const B&prev)const{B r;if(p.mode==0)r=p.body;else if(p.mode<5)r=unrle(p.body,s.n());else r=unzip(p.body,s.n());ck(r.size()==s.n(),"raw size");if(p.mode==2||p.mode==6)r=xorv(r,prev);if(p.mode==3||p.mode==7)r=xorv(r,motion(prev));if(p.mode==4||p.mode==8)r=xorv(r,ann(prev,motion(prev),mean(prev),p.w));return r;}
};
void choose(Packet&b,Packet&&q){if(q.size()<b.size())b=std::move(q);} Packet coded(int m,const B&r,W w,bool z){Packet p{m,rle(r),w};if(z){Packet q{m+4,zip(r),w};choose(p,std::move(q));}return p;}
void write(std::ostream&f,const Packet&p,uint32_t h){f.put(char(p.mode));put32(f,p.body.size());put32(f,h);if(p.mode==4||p.mode==8)for(int w:p.w)f.put(char(w));f.write((const char*)p.body.data(),p.body.size());}
U rng=0x9E3779B97F4A7C15ULL;U randu(){rng^=rng<<13;rng^=rng>>7;rng^=rng<<17;return rng;}
W mutate(W w){int a=randu()%3,b=(a+1+randu()%2)%3;if(w[a]){--w[a];++w[b];}else if(w[b]){--w[b];++w[a];}return w;}
struct Stats{U it=0,bytes=0,base=0,fixed=0,accept=0,evaluated=0,skipped=0,words=0,changes=0,cmp=0,hash=14695981039346656037ULL;std::array<U,9> modes{};};
// 12 native opcode dispatches; operand is block index and low bits route functional domain.
const std::array<int,12> ops={10,0,9,3,4,2,8,1,5,12,13,6},lanes={0,2,1,1,1,1,2,0,3,3,0,3};
void run(const Kernel&k,const B&t,B&p,W&w,U i,bool z,Stats&st,std::ostream*out,bool optimize,bool fast){B m,a,inc,cand,rest,raw;W trial=w;Packet base,best,pi,pc,fx;uint32_t h=0;bool accept=false,skip=false;for(int j=0;j<12;++j){U word=(U(ops[j])<<60)|(i<<2)|lanes[j];ck(((word>>2)&((1ULL<<58)-1))==i && (word&3)==U(lanes[j]),"isa");++st.words;switch(word>>60){case 10:break;case 0:raw=t;break;case 9:m=k.motion(p);break;case 3:if(!fast)a=k.mean(p);break;case 4:trial=mutate(w);break;case 2:if(!fast){inc=k.ann(p,m,a,w);cand=k.ann(p,m,a,trial);}break;case 8:{base={0,raw,{16,0,0}};choose(base,coded(1,raw,w,z));choose(base,coded(2,xorv(raw,p),w,z));choose(base,coded(3,xorv(raw,m),w,z));if(fast && base.size()<=12+size_t(z?1:(k.s.n()+127)/128)){skip=true;++st.skipped;best=base;st.fixed+=base.size();break;}if(fast){a=k.mean(p);inc=k.ann(p,m,a,w);cand=k.ann(p,m,a,trial);}++st.evaluated;pi=coded(4,xorv(raw,inc),w,z);pc=coded(4,xorv(raw,cand),trial,z);fx=coded(4,xorv(raw,k.ann(p,m,a,{6,5,5})),{6,5,5},z);Packet fixed=base;choose(fixed,std::move(fx));st.fixed+=fixed.size();best=base;choose(best,Packet(pi));if(optimize&&pc.size()<pi.size()&&pc.size()<base.size()){accept=true;choose(best,Packet(pc));}break;}case 1:h=crc(t);break;case 5:rest=k.decode(best,p);break;case 12:ck(rest==t&&crc(rest)==h,"verification");if(!skip){ck(k.decode(pc,p)==t,"candidate verification");st.cmp+=t.size();}st.cmp+=t.size();break;case 13:if(accept){w=trial;++st.accept;}if(out)write(*out,best,h);st.bytes+=best.size();st.base+=base.size();++st.modes[best.mode];for(size_t q=0;q<p.size();++q)st.changes+=p[q]!=t[q];p=std::move(rest);break;case 6:st.hash^=h;st.hash*=1099511628211ULL;++st.it;break;default:throw std::runtime_error("opcode");}}}
int main(int argc,char**argv){try{ck(argc==12,"usage: core input output z y x c iterations export_count zlib optimize seed");Shape s{std::stoi(argv[3]),std::stoi(argv[4]),std::stoi(argv[5]),std::stoi(argv[6])};ck(s.z>0&&s.y>0&&s.x>0&&s.c>0&&s.n()<=1000000,"shape");U n=std::stoull(argv[7]),ex=std::stoull(argv[8]);bool z=std::stoi(argv[9]),opt=std::stoi(argv[10]),fast=std::stoi(argv[10])==2;rng=std::stoull(argv[11]);ck(rng&&n&&ex<=n&&n<(1ULL<<58),"count");std::ifstream f(argv[1],std::ios::binary|std::ios::ate);ck(bool(f),"input");size_t sz=f.tellg();ck(sz&&sz%s.n()==0,"input size");B all(sz);f.seekg(0);f.read((char*)all.data(),sz);ck(bool(f),"read");std::ofstream o(argv[2],std::ios::binary);ck(bool(o),"output");o.write("S3B8",4);for(auto v:{s.z,s.y,s.x,s.c})put32(o,v);put32(o,ex);Kernel k(s);B p(s.n()),t(s.n());W w={6,5,5};Stats st;auto start=std::chrono::steady_clock::now();for(U i=0;i<n;++i){size_t off=(i%(sz/s.n()))*s.n();std::copy_n(all.begin()+off,s.n(),t.begin());run(k,t,p,w,i,z,st,i<ex?&o:nullptr,opt,fast);}o.close();ck(bool(o),"write");double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::cout<<"{\"iterations\":"<<st.it<<",\"instructions\":"<<st.words<<",\"candidate_evaluations\":"<<st.evaluated<<",\"skipped\":"<<st.skipped<<",\"accepted\":"<<st.accept<<",\"verified_byte_comparisons\":"<<st.cmp<<",\"record_bytes\":"<<st.bytes<<",\"baseline_bytes\":"<<st.base<<",\"fixed_model_bytes\":"<<st.fixed<<",\"changed_bytes\":"<<st.changes<<",\"seconds\":"<<sec<<",\"hash_chain\":\""<<std::hex<<st.hash<<std::dec<<"\",\"weights\":["<<w[0]<<","<<w[1]<<","<<w[2]<<"],\"modes\":[";for(int i=0;i<9;++i)std::cout<<(i?",":"")<<st.modes[i];std::cout<<"]}\n";}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
